EPOCH = 1288834974657  # custom origin, not unix epoch
WORKER_BITS = 10
SEQ_BITS = 12
MAX_SEQ = (1 << SEQ_BITS) - 1

class Snowflake:
    def __init__(self, worker_id: int):
        assert 0 <= worker_id < (1 << WORKER_BITS)
        self.worker_id = worker_id
        self.last_millis = -1
        self.seq = 0
        self.lock = __import__('threading').Lock()

    def _millis(self) -> int:
        import time
        return int(time.time() * 1000)

    def next_id(self) -> int:
        with self.lock:  # per-process mutual exclusion is mandatory
            now = self._millis()
            if now < self.last_millis:
                # Never mint backwards. Throw, sleep, or fail over.
                raise ClockWentBackwards(now, self.last_millis)
            if now == self.last_millis:
                self.seq = (self.seq + 1) & MAX_SEQ
                if self.seq == 0:
                    # 4096 consumed in this ms: park until next tick
                    while now <= self.last_millis:
                        now = self._millis()
            else:
                self.seq = 0
            self.last_millis = now
            return ((now - EPOCH) << 22) | (self.worker_id << 12) | self.seq

public final class SnowflakeDecode {
    static final long EPOCH = 1288834974657L;
    public record Parts(long millis, int workerId, int seq) {}
    public static Parts decode(long id) {
        int seq = (int)(id & 0xFFF);              // low 12 bits
        int workerId = (int)((id >>> 12) & 0x3FF); // next 10 bits
        long millis = (id >>> 22) + EPOCH;         // high 41 bits
        return new Parts(millis, workerId, seq);
    }
    // Debugging rule: group duplicate-key incidents by workerId.
    // Same workerId + same millis + same seq = clock or lease bug.
}
